def solve(n):
    def dfs(path, used_diffs, used_vals):
        if len(path) == n:
            return path

        last = path[-1]
        for diff in range(n-1, 0, -1):
            if diff not in used_diffs:
                # Try last + diff
                if last + diff < n and (last + diff) not in used_vals:
                    used_vals.add(last + diff)
                    used_diffs.add(diff)
                    res = dfs(path + [last + diff], used_diffs, used_vals)
                    if res: return res
                    used_vals.remove(last + diff)
                    used_diffs.remove(diff)
                # Try last - diff
                if last - diff >= 0 and (last - diff) not in used_vals:
                    used_vals.add(last - diff)
                    used_diffs.add(diff)
                    res = dfs(path + [last - diff], used_diffs, used_vals)
                    if res: return res
                    used_vals.remove(last - diff)
                    used_diffs.remove(diff)
        return None

    for i in range(n):
        res = dfs([i], set(), {i})
        if res:
            return res
    return None

print(solve(11))
